#if UNITY_EDITOR
using System;using System.IO;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class PrisonOfficeCheck {
static bool shot;static int step;static float wait;static bool running;static double deadline;
static PrisonOfficeCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("OfficeCheck",false)){SessionState.SetBool("OfficeCheck",false);running=true;step=0;deadline=EditorApplication.timeSinceStartup+50;}};}
public static void Run(){shot=false;File.WriteAllText("Logs/Prison-office-check.txt","");SessionState.SetBool("OfficeCheck",true);EditorApplication.EnterPlaymode();}
static void Check(bool b,string s){File.AppendAllText("Logs/Prison-office-check.txt",(b?"PASS ":"FAIL ")+s+"\n");if(!b)throw new Exception(s);}
public static void ContinueChapter(){File.WriteAllText("Logs/Prison-office-check.txt","Continuous chapter test; previous mission state retained\n");running=true;step=1;wait=Time.time+.5f;deadline=EditorApplication.timeSinceStartup+200;}
        static void Tick(){if(!running||!EditorApplication.isPlaying)return;try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("timeout");var m=Object.FindFirstObjectByType<PrisonOfficeSearch>();if(!m)return;if(step==0){wait=Time.time+2;step++;return;}if(!shot&&step==5&&Time.time>wait-1.5f){shot=true;PrisonChickenCheck.Capture(m.previous.previous.prison.player.View,"Logs/Prison-office-pickup.png");}if(Time.time<wait)return;var p=m.previous.previous.prison.player;
 if(step==1){if(PrisonChapterCheck.Active){shot=false;step=2;return;}var intro=m.previous.previous.prison.introduction;intro.StopAllCoroutines();typeof(PrisonIntroduction).GetMethod("SetCinematic",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(intro,new object[]{false});typeof(PrisonIntroduction).GetProperty("State").SetValue(intro,PrisonIntroduction.Stage.Complete);Check(!m.points[0].TryInteract(),"search locked before warden sleeps");typeof(PrisonKeysMission).GetProperty("State").SetValue(m.previous,PrisonKeysMission.Stage.Complete);step++;wait=Time.time+.5f;return;}
 if(step==2){Check(m.Active,"warden completion unlocks office search");m.previous.previous.prison.introduction.mingi.agent.Warp(new Vector3(-22,3.75f,-25));Place(p,m.points[2].transform.position);Check(m.points[2].TryInteract()&&m.KnowsPassword,"password readable first in any order");Check(m.Notes.Contains(m.dialogue.password),"password saved in phone notes");Check(!m.Complete,"reading password alone does not complete mission");Place(p,m.points[0].transform.position);Check(m.points[0].TryInteract(),"uniform drawer opens");step++;wait=Time.time+.7f;return;}
 if(step==3){Check(m.points[0].Opened&&m.points[0].TryInteract(),"uniforms collected after drawer opens");Check(!m.points[0].TryInteract(),"duplicate pickup blocked");step=5;wait=Time.time+2.8f;return;}
 if(step==5){Check(m.HasUniforms,"uniform pickup animation completes");Place(p,m.points[1].transform.position);Check(m.points[1].TryInteract(),"key drawer opens");step=6;wait=Time.time+.7f;return;} if(step==6){Check(m.points[1].TryInteract(),"key pickup starts");step=4;wait=Time.time+2.8f;return;} if(step==4){Check(m.HasVehicleKey&&m.Complete,"vehicle key completes all three objectives");Check(p.CanAct&&m.Target==null,"control retained and objective marker cleared");Place(p,m.points[2].transform.position);Check(m.points[2].TryInteract(),"password can be reread after completion");File.AppendAllText("Logs/Prison-office-check.txt","NOTE interactions tested with travel seeded; manual full traversal not performed\n");running=false;if(PrisonChapterCheck.Active)PrisonChapterCheck.Finish(!System.IO.File.ReadAllText("Logs/Prison-office-check.txt").Contains("Exception"));else EditorApplication.ExitPlaymode();}
 }catch(Exception e){File.AppendAllText("Logs/Prison-office-check.txt",e.ToString());running=false;if(PrisonChapterCheck.Active)PrisonChapterCheck.Finish(!System.IO.File.ReadAllText("Logs/Prison-office-check.txt").Contains("Exception"));else EditorApplication.ExitPlaymode();}}
static void Place(PlayerCombat p,Vector3 t){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=new Vector3(t.x,4.85f,t.z-1);cc.enabled=true;p.View.transform.LookAt(t+Vector3.up*.65f);Physics.SyncTransforms();}
}}
#endif
